// -----------------------------------------------------------------------------
// Real-world telegram layouts, one per supported variant. The CRC is computed
// when the fixture is built (`withCrc`), so a fixture can be edited without
// recomputing it by hand (test/dsmr.test.js checks the CRC implementation
// against the reference check value of CRC-16/ARC).
// -----------------------------------------------------------------------------

import { crc16 } from '../../src/dsmr/crc.js';

const crlf = (lines) => lines.join('\r\n');

/** Append the CRC line to a telegram body ending with `!`. */
export function withCrc(body) {
  return `${body}${crc16(body).toString(16).toUpperCase().padStart(4, '0')}\r\n`;
}

