/**
 * Build a Dutch DSMR 5 telegram with custom values (scene event tests).
 * @param {object} values
 */
export function nlTelegram({
  timestamp = '261014120000S',
  tariff = '0002',
  importPower = '01.193',
  exportPower = '00.000',
  importT1 = '001000.000',
  importT2 = '002000.000',
  exportT1 = '000100.000',
  exportT2 = '000200.000',
  failures = '00004',
  longFailures = '00002',
  gas = '01000.000',
} = {}) {
  return withCrc(
    crlf([
      '/ISk5\\2MT382-1000',
      '',
      '1-3:0.2.8(50)',
      `0-0:1.0.0(${timestamp})`,
      '0-0:96.1.1(4B384547303034303436333935353037)',
      `1-0:1.8.1(${importT1}*kWh)`,
      `1-0:1.8.2(${importT2}*kWh)`,
      `1-0:2.8.1(${exportT1}*kWh)`,
      `1-0:2.8.2(${exportT2}*kWh)`,
      `0-0:96.14.0(${tariff})`,
      `1-0:1.7.0(${importPower}*kW)`,
      `1-0:2.7.0(${exportPower}*kW)`,
      `0-0:96.7.21(${failures})`,
      `0-0:96.7.9(${longFailures})`,
      '1-0:32.7.0(230.1*V)',
      '1-0:31.7.0(005*A)',
      `1-0:21.7.0(${importPower}*kW)`,
      `1-0:22.7.0(${exportPower}*kW)`,
      '0-1:24.1.0(003)',
      '0-1:96.1.0(3232323241424344313233343536373839)',
      `0-1:24.2.1(${timestamp})(${gas}*m3)`,
      '!',
    ]),
  );
}
